// Throwaway manual-QA probe: prints the EXACT update payload the handlers now send.
// No DB. Re-implements nothing — it imports the real production helper via tsx-free
// transpile by calling the same logic path the handlers use.
import { readFileSync } from "node:fs";

// The helper is pure; extract and eval it straight from the production source so this
// probe cannot drift from what actually ships.
const src = readFileSync(
  "app/api/supa/handlers/exam-handlers.ts",
  "utf8"
).replace(/\r\n/g, "\n");

const start = src.indexOf("export function buildAiDraftPreservation");
const end = src.indexOf("\n}", src.indexOf("return { ai_draft_questions")) + 2;
const fnSrc = src
  .slice(start, end)
  .replace("export function", "function")
  // strip TS annotations for plain-node eval
  .replace(
    /\(\s*current:[\s\S]*?\)\s*:\s*\{[^}]*\}\s*\|\s*null\s*\{/,
    "(current, nextQuestions, now = new Date().toISOString()) {"
  );

const buildAiDraftPreservation = new Function(`${fnSrc}; return buildAiDraftPreservation;`)();

const AI_DRAFT = [
  { id: "q1", text: "AI가 생성한 1번 문항", type: "essay" },
  { id: "q2", text: "AI가 생성한 2번 문항", type: "essay" },
];
const INSTRUCTOR_EDIT = [
  { id: "q1", text: "교수자가 고쳐 쓴 1번 문항", type: "essay" },
  { id: "q2", text: "AI가 생성한 2번 문항", type: "essay" },
];

/** Mirrors updateExam: updateWithoutRubric + conditional Object.assign(aiDraft). */
function buildUpdatePayload(storedExam, update) {
  const payload = { ...update };
  delete payload.rubric;
  delete payload.rubric_public;
  if ("questions" in payload) {
    const aiDraft = buildAiDraftPreservation(storedExam, payload.questions);
    if (aiDraft) Object.assign(payload, aiDraft);
  }
  return payload;
}

const show = (label, payload) => {
  console.log(`\n===== ${label} =====`);
  console.log(JSON.stringify(payload, null, 2));
  console.log(`keys: ${JSON.stringify(Object.keys(payload))}`);
  console.log(`has ai_draft_questions   : ${"ai_draft_questions" in payload}`);
  console.log(`has ai_draft_generated_at: ${"ai_draft_generated_at" in payload}`);
};

// (a) first AI commit — exam has no questions and no draft yet
show(
  "(a) FIRST AI COMMIT",
  buildUpdatePayload(
    { id: "exam-1", questions: [], ai_draft_questions: null },
    { questions: AI_DRAFT, updated_at: "2026-08-11T09:00:00.000Z" }
