+// transpile by calling the same logic path the handlers use.
+import { readFileSync } from "node:fs";
+
+// The helper is pure; extract and eval it straight from the production source so this
+// probe cannot drift from what actually ships.
+const src = readFileSync(
+  "app/api/supa/handlers/exam-handlers.ts",
+  "utf8"
+).replace(/\r\n/g, "\n");
+
+const start = src.indexOf("export function buildAiDraftPreservation");
+const end = src.indexOf("\n}", src.indexOf("return { ai_draft_questions")) + 2;
+const fnSrc = src
+  .slice(start, end)
+  .replace("export function", "function")
+  // strip TS annotations for plain-node eval
+  .replace(
+    /\(\s*current:[\s\S]*?\)\s*:\s*\{[^}]*\}\s*\|\s*null\s*\{/,
+    "(current, nextQuestions, now = new Date().toISOString()) {"
+  );
+
+const buildAiDraftPreservation = new Function(`${fnSrc}; return buildAiDraftPreservation;`)();
+
+const AI_DRAFT = [
+  { id: "q1", text: "AI가 생성한 1번 문항", type: "essay" },
